WITH valid AS (SELECT *, CASE WHEN browser IN ('Safari', 'Firefox') THEN 'Core' ELSE 'Other' END AS browser_group, COALESCE(country, 'UNKNOWN') AS country_filled FROM sessions WHERE started_at >= DATE '2023-05-27'), with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM valid), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), deduped AS (SELECT *, RANK() OVER (PARTITION BY customer_id ORDER BY started_at DESC NULLS LAST) AS latest_rank FROM sessionized QUALIFY latest_rank = 1) SELECT id, device, browser, started_at, country, country_filled, latest_rank, CASE WHEN device RLIKE '^(mobile|tablet)$' THEN 'OTHER_ZONE' WHEN device RLIKE '^(desktop)$' THEN 'GROUP_B' ELSE 'CORE' END AS device_zone FROM deduped;
